let next=0;
export const field=(text='')=>({type:'Text',id:'f'+(++next),text});
export const sequence=()=>({type:'Sequence',children:[field()]});
export function template(type,name=''){const child=()=>sequence();return type==='Fraction'?{type,numerator:child(),denominator:child()}:type==='Power'?{type,base:child(),exponent:child()}:type==='Root'?{type,index:sequence(),body:child()}:type==='Sqrt'?{type,body:child()}:type==='Function'?{type,name,body:child()}:{type:'Group',body:child()};}
export function children(node){return node.type==='Sequence'?node.children:node.type==='Fraction'?[node.numerator,node.denominator]:node.type==='Power'?[node.base,node.exponent]:node.type==='Root'?[node.index,node.body]:node.body?[node.body]:[];}
export function fields(node){return node.type==='Text'?[node]:children(node).flatMap(fields);}
export function serialize(node){switch(node.type){case'Text':return node.text;case'Sequence':return node.children.map(serialize).join('');case'Fraction':return`((${serialize(node.numerator)})/(${serialize(node.denominator)}))`;case'Power':return`((${serialize(node.base)})^(${serialize(node.exponent)}))`;case'Root':return`root(${serialize(node.index)},${serialize(node.body)})`;case'Sqrt':return`sqrt(${serialize(node.body)})`;case'Function':return`${node.name}(${serialize(node.body)})`;case'Group':return`(${serialize(node.body)})`;default:throw Error('syntax');}}
export function insert(root,id,start,end,type,name){const target=fields(root).find(f=>f.id===id);if(!target)return null;let parent;const visit=n=>{if(n.type==='Sequence'&&n.children.includes(target))parent=n;else children(n).forEach(visit)};visit(root);const node=template(type,name),before=target.text.slice(0,start),selected=target.text.slice(start,end),after=target.text.slice(end);let focus=fields(node)[0];if(type==='Power'){node.base.children[0].text=selected||before;target.text=selected?before:'';focus=node.exponent.children[0];}else{target.text=before;if(selected)focus.text=selected;}parent.children.splice(parent.children.indexOf(target)+1,0,node,field(after));return focus.id;}
export function navigate(root,id,direction){const all=fields(root),at=all.findIndex(f=>f.id===id);if(direction==='left'||direction==='right')return all[at+(direction==='left'?-1:1)]?.id??id;let match;const visit=n=>{const parts=children(n);if(['Fraction','Power','Root'].includes(n.type)){const index=parts.findIndex(p=>fields(p).some(f=>f.id===id));if(index>=0){const target=parts[direction==='up'?0:1];match=fields(target)[0].id;}}parts.forEach(visit)};visit(root);return match??id;}
export function unwrapEmpty(root,id){let removed=false;const visit=n=>{if(n.type==='Sequence'){for(let i=0;i<n.children.length;i++){const x=n.children[i];if(x.type!=='Text'&&fields(x).some(f=>f.id===id)&&fields(x).every(f=>!f.text)){n.children.splice(i,1);removed=true;return;}}}children(n).forEach(visit)};visit(root);return removed;}

export function exitStructure(root,id){let found;const visit=n=>{if(n.type==='Sequence')for(let i=0;i<n.children.length;i++){const child=n.children[i];if(child.type!=='Text'&&fields(child).some(f=>f.id===id)){found=fields(n.children[i+1]||child)[0].id;visit(child);}}else children(n).forEach(visit);};visit(root);return found??id;}
